const BINARY = {
  '+': { prec: 1, assoc: 'left' },
  '-': { prec: 1, assoc: 'left' },
  '*': { prec: 2, assoc: 'left' },
  '/': { prec: 2, assoc: 'left' },
  '%': { prec: 2, assoc: 'left' },
  '^': { prec: 4, assoc: 'right' },
